    90	func (c *SimpleCompactor) MaybeCompact(ctx context.Context, req CompactionRequest) (CompactionResult, error) {
    91		result := CompactionResult{Messages: req.Messages}
    92		if c == nil {
    93			return result, nil
    94		}
    95	
    96		result.Due = req.Force || c.shouldCompact(req)
    97		if !result.Due {
    98			return result, nil
    99		}
   100		if c.Client == nil {
   101			result.Reason = "compaction is unavailable"
   102			return result, nil
   103		}
   104	
   105		keepUserTurns := c.keepUserTurns(req.Options)
   106		if req.KeepUserTurns != nil {
   107			keepUserTurns = *req.KeepUserTurns
   108		}
   109		prefix, previousSummary, archive, suffix, _, ok := splitCompactionMessages(req.Messages, keepUserTurns)
   110		if !ok || len(archive) == 0 {
   111			result.Reason = "nothing to compact"
   112			return result, nil
   113		}
   114	
   115		summary, err := c.summarize(ctx, req, previousSummary, archive)
   116		if err != nil {
   117			result.Reason = err.Error()
   118			return result, err
   119		}
   120		summary = truncateCompactionSummary(strings.TrimSpace(summary))
   121		if summary == "" {
   122			summary, err = c.summarizeEmptyFallback(ctx, req, previousSummary, archive)
   123			if err != nil {
   124				result.Reason = err.Error()
   125				return result, err
   126			}
   127			summary = truncateCompactionSummary(strings.TrimSpace(summary))
   128		}
   129		if summary == "" {
   130			result.Reason = "summary was empty"
   131			return result, nil
   132		}
   133	
   134		compacted := make([]api.Message, 0, len(prefix)+len(suffix)+2)
   135		compacted = append(compacted, prefix...)
   136		compacted = append(compacted, CompactionSummaryMessages(summary, req.ContinueTask)...)
   137		compacted = append(compacted, suffix...)
   138		result.Messages = compacted
   139		result.Compacted = true
   140		result.Summary = summary
   141		return result, nil
   142	}
