   144	func (c *SimpleCompactor) shouldCompact(req CompactionRequest) bool {
   145		contextWindow := c.contextWindowTokens(req.Options)
   146		threshold := int(float64(contextWindow) * c.threshold())
   147		if threshold <= 0 {
   148			return false
   149		}
   150		if req.Latest.PromptEvalCount > 0 && req.Latest.PromptEvalCount >= threshold {
   151			return true
   152		}
   153		return estimateCompactionRequestTokens(req) >= threshold
   154	}
