   230	func (c *SimpleCompactor) summarize(ctx context.Context, req CompactionRequest, previousSummary string, archive []api.Message) (string, error) {
   231		body, err := compactionPrompt(previousSummary, archive, c.compactionPromptBodyBudgetTokens(req.Options))
   232		if err != nil {
   233			return "", err
   234		}
   235	
   236		chatReq := &api.ChatRequest{
   237			Model: req.Model,
   238			Messages: []api.Message{
   239				{
   240					Role:    "system",
   241					Content: compactionSystemPrompt,
   242				},
   243				{
   244					Role:    "user",
   245					Content: body,
   246				},
   247			},
   248			Options: req.Options,
   249			Think:   req.Think,
   250		}
   251		if req.KeepAlive != nil {
   252			chatReq.KeepAlive = req.KeepAlive
   253		}
   254	
   255		var summary strings.Builder
   256		if err := c.Client.Chat(ctx, chatReq, func(response api.ChatResponse) error {
   257			summary.WriteString(response.Message.Content)
   258			if req.Progress != nil {
   259				tokens := response.EvalCount
