   367	func estimateMessagesTokens(messages []api.Message) int {
   368		var total int
   369		for _, msg := range messages {
   370			total += estimateCompactionTokens(msg.Role)
   371			total += estimateCompactionTokens(msg.Content)
   372			total += estimateCompactionTokens(msg.Thinking)
   373			total += estimateCompactionTokens(msg.ToolName)
   374			total += estimateCompactionTokens(msg.ToolCallID)
   375			for _, call := range msg.ToolCalls {
   376				total += estimateCompactionTokens(call.Function.Name)
   377				total += estimateCompactionTokens(call.Function.Arguments.String())
   378			}
   379		}
   380		return total
   381	}
