   383	func estimateCompactionRequestTokens(req CompactionRequest) int {
   384		requestMessages := sanitizeMessagesForEstimate(req.Messages)
   385		if strings.TrimSpace(req.SystemPrompt) != "" {
   386			requestMessages = make([]api.Message, 0, len(req.Messages)+1)
   387			requestMessages = append(requestMessages, api.Message{Role: "system", Content: strings.TrimSpace(req.SystemPrompt)})
   388			requestMessages = append(requestMessages, sanitizeMessagesForEstimate(req.Messages)...)
   389		}
   390	
   391		payload := struct {
   392			Messages []api.Message   `json:"messages,omitempty"`
   393			Tools    api.Tools       `json:"tools,omitempty"`
   394			Format   json.RawMessage `json:"format,omitempty"`
   395		}{
   396			Messages: requestMessages,
   397			Tools:    req.Tools,
   398		}
   399		if rawFormat, ok := compactionFormatForEstimate(req.Format); ok {
   400			payload.Format = rawFormat
   401		}
   402		if data, err := json.Marshal(payload); err == nil {
   403			return estimateCompactionTokens(string(data))
   404		}
   405	
   406		total := estimateMessagesTokens(requestMessages)
   407		total += estimateCompactionTokens(req.Tools.String())
   408		total += estimateCompactionTokens(req.Format)
   409		return total
   410	}
